"    const rowsToAdd = talentsList.map((t, idx) => {
      const id = t.id || ('PGE-' + String(idx + 1).padStart(3, '0'));
      const now = new Date().toISOString();
      const skills = Array.isArray(t.skills) ? t.skills : [];
      const links = typeof t.links === 'object' && t.links ? t.links : {};

      return [
        id,
        t.name || '',
        t.role || 'Freelance Content Creator',
        formatToInternationalPhone(t.phone),
        t.email || '',
        t.experienceLevel || 'Junior',
        Number(t.overallRating) || 4,
        JSON.stringify(skills),
        t.stage || 'Interviewed',
        t.expectedSalary || 'Standard Uang Saku',
        t.cvUrl || '',
        t.cvFileId || '',
        t.portfolioUrl || '',
        t.portfolioFileId || '',
        JSON.stringify(links),
        t.notes || '',
        t.createdAt || now,
        now
      ];
    });

    const startRow = sheet.getLastRow() + 1;
    sheet.getRange(startRow, 1, rowsToAdd.length, CONFIG.HEADERS.length).setValues(rowsToAdd);

    return { success: true, count: rowsToAdd.length, message: `Successfully imported ${rowsToAdd.length} candidates.` };
  } catch (error) {
    Logger.log('importTalentsBulk Error: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

/**
 * Updates an existing talent record
 */
function updateTalent(talentData) {
  try {
    const sheet = getSheet();
    const data = sheet.getDataRange().getValues();
    const id = String(talentData.id);
    let rowIndex = -1;

    for (let i = 1; i < data.length; i++) {
      if (String(data[i][0]) === id) {
        rowIndex = i + 1;
        break;
      }
    }

    if (rowIndex === -1) {
      return { success: false, error: 'Candidate record not found.' };
    }

    const existingRow = data[rowIndex - 1];
    const talent = { ...talentData };
    talent.phone = formatToInternationalPhone(talent.phone || existingRow[3]);
    talent.updatedAt = new Date().toISOString();"

